<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import PageHeader from "@/components/PageHeader.vue";
import { ApiError } from "@/services/http";
import { downloadReportSummary, getReportOptions, getReportSummary, type ReportFilter, type ReportOptions, type ReportSummary } from "@/services/reportes";

const report = ref<ReportSummary | null>(null); const loading = ref(false); const optionsLoading = ref(false); const exporting = ref(false); const error = ref(""); const optionsError = ref(""); const exportError = ref(""); const options = ref<ReportOptions>({ campus: [], edificios: [], tiposBeneficiario: [] });
const filters = ref<ReportFilter>({ estado: "all", desde: "", hasta: "" });
const filteredBuildings = computed(() => options.value.edificios.filter(item => !filters.value.idCampus || item.idCampus === filters.value.idCampus));
const message = (cause: unknown) => cause instanceof ApiError ? cause.message : "No fue posible cargar los reportes.";
const value = (item: number | string) => String(item);
async function load() { loading.value = true; error.value = ""; try { report.value = await getReportSummary(filters.value); } catch (cause) { report.value = null; error.value = message(cause); } finally { loading.value = false; } }
async function exportCsv() { exporting.value = true; exportError.value = ""; try { const blob = await downloadReportSummary(filters.value); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "reportes-siga.csv"; anchor.click(); URL.revokeObjectURL(url); } catch (cause) { exportError.value = message(cause); } finally { exporting.value = false; } }
async function loadOptions() { optionsLoading.value = true; optionsError.value = ""; try { options.value = await getReportOptions(); } catch (cause) { optionsError.value = message(cause); } finally { optionsLoading.value = false; } }
watch(() => filters.value.idCampus, () => { if (filters.value.idEdificio && !filteredBuildings.value.some(item => item.idEdificio === filters.value.idEdificio)) filters.value.idEdificio = undefined; });
onMounted(() => { void load(); void loadOptions(); });
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Operación' }, { label: 'Reportes y Estadísticas' }]" />
  <PageHeader eyebrow="Operación" title="Reportes y Estadísticas" description="Indicadores calculados con información persistida en SQL Server." />
  <section class="bo-card reports-filters"><form class="bo-toolbar" @submit.prevent="load"><label>Estado<select v-model="filters.estado"><option value="all">Todos</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select></label><label>Campus<select v-model="filters.idCampus" :disabled="optionsLoading"><option :value="undefined">Todos los campus</option><option v-for="item in options.campus" :key="item.idCampus" :value="item.idCampus">{{ item.nombreCampus }}</option></select></label><label>Edificio<select v-model="filters.idEdificio" :disabled="optionsLoading || !filteredBuildings.length"><option :value="undefined">Todos los edificios</option><option v-for="item in filteredBuildings" :key="item.idEdificio" :value="item.idEdificio">{{ item.nombreEdificio }}</option></select></label><label>Tipo de beneficiario<select v-model="filters.idTipoBeneficiario" :disabled="optionsLoading"><option :value="undefined">Todos los tipos</option><option v-for="item in options.tiposBeneficiario" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Desde<input v-model="filters.desde" type="date" /></label><label>Hasta<input v-model="filters.hasta" type="date" /></label><button class="bo-btn bo-btn-primary">Actualizar</button><button type="button" class="bo-btn" :disabled="exporting || loading || !report" @click="exportCsv">{{ exporting ? 'Exportando...' : 'Exportar CSV' }}</button></form><p v-if="optionsLoading" class="bo-form-note">Cargando catálogos...</p><p v-if="optionsError" class="bo-form-note bo-state-error">{{ optionsError }} Los reportes pueden consultarse sin filtros de catálogo.</p><p class="bo-form-note">Los filtros de campus y edificio aplican a la infraestructura; el tipo de beneficiario y las fechas aplican a beneficiarios, solicitudes y asignaciones cuando existe relación en el modelo.</p></section>
  <div v-if="error" class="bo-state bo-state-error"><strong>{{ error }}</strong><button class="bo-btn" @click="load">Reintentar</button></div><div v-if="exportError" class="bo-notice alert--error">{{ exportError }}</div>
  <div v-if="loading" class="bo-state">Calculando indicadores...</div><div v-else-if="!report" class="bo-state">No hay información disponible para mostrar.</div>
  <template v-else>
    <section class="reports-kpis"><article class="bo-card"><small>Beneficiarios</small><strong>{{ value(report.beneficiarios.total) }}</strong></article><article class="bo-card"><small>Solicitudes</small><strong>{{ value(report.solicitudes.total) }}</strong></article><article class="bo-card"><small>Asignaciones vigentes</small><strong>{{ value(report.asignacionesVigentes) }}</strong></article><article class="bo-card"><small>Campus</small><strong>{{ value(report.infraestructura.campus) }}</strong></article><article class="bo-card"><small>Edificios</small><strong>{{ value(report.infraestructura.edificios) }}</strong></article><article class="bo-card"><small>Elevadores</small><strong>{{ value(report.infraestructura.elevadores) }}</strong></article><article class="bo-card"><small>Dispositivos</small><strong>{{ value(report.infraestructura.dispositivos) }}</strong></article></section>
    <section class="reports-panels"><article class="bo-card reports-panel"><h2>Beneficiarios por tipo</h2><div v-if="!report.beneficiarios.porTipo.length" class="bo-state">No hay registros para este indicador.</div><table v-else><thead><tr><th>Tipo</th><th>Total</th></tr></thead><tbody><tr v-for="item in report.beneficiarios.porTipo" :key="item.codigoTipo"><td>{{ item.nombreTipo }}</td><td>{{ value(item.total) }}</td></tr></tbody></table></article><article class="bo-card reports-panel"><h2>Solicitudes por estado</h2><div v-if="!report.solicitudes.porEstado.length" class="bo-state">No hay registros para este indicador.</div><table v-else><thead><tr><th>Estado</th><th>Total</th></tr></thead><tbody><tr v-for="item in report.solicitudes.porEstado" :key="item.codigoEstado"><td>{{ item.nombreEstado }}</td><td>{{ value(item.total) }}</td></tr></tbody></table></article><article class="bo-card reports-panel"><h2>Tarjetas por estado</h2><div v-if="!report.tarjetas.porEstado.length" class="bo-state">No hay registros para este indicador.</div><table v-else><thead><tr><th>Estado</th><th>Total</th></tr></thead><tbody><tr v-for="item in report.tarjetas.porEstado" :key="item.codigoEstado"><td>{{ item.nombreEstado }}</td><td>{{ value(item.total) }}</td></tr></tbody></table></article></section>
  </template>
</template>

<style scoped>
.reports-filters label { display: grid; gap: 5px; color: var(--bo-dark); font-size: 11px; font-weight: 700; }.reports-filters input,.reports-filters select { height: 34px; padding: 0 8px; border: 1px solid var(--bo-line); border-radius: 6px; font: inherit; }.reports-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin: 16px 0; }.reports-kpis article { display: grid; gap: 8px; padding: 16px; }.reports-kpis small { color: var(--bo-muted); font-size: 11px; }.reports-kpis strong { color: var(--bo-dark); font-size: 24px; }.reports-panels { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }.reports-panel { overflow: hidden; }.reports-panel h2 { margin: 0; padding: 16px; color: var(--bo-dark); font-size: 15px; }.reports-panel table { width: 100%; border-collapse: collapse; }.reports-panel th,.reports-panel td { padding: 10px 16px; border-top: 1px solid var(--bo-line); text-align: left; font-size: 12px; }.reports-panel th { color: var(--bo-muted); font-size: 10px; text-transform: uppercase; }.reports-panel td:last-child,.reports-panel th:last-child { text-align: right; font-variant-numeric: tabular-nums; }.reports-panel .bo-state { min-height: 110px; }
@media (max-width: 1000px) { .reports-kpis { grid-template-columns: repeat(3, minmax(0, 1fr)); }.reports-panels { grid-template-columns: 1fr; } } @media (max-width: 650px) { .reports-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
</style>
